"""Box detector (YOLO11 or RT-DETR, Ultralytics) on the route-grouped Bangladesh split. Generated by build_jobs.py.
Outputs: results_<NAME>.json, test_preds_<NAME>.csv (normalised xyxy + score), <NAME>_best.pt."""
import os, glob, json, shutil, subprocess, csv, io, time
SPLIT_CSV = """__SPLIT_CSV__"""
R = glob.glob('/kaggle/input/**/roadside-trees-of-bangladesh-street-view', recursive=True)[0]
src = {'BD_740': f'{R}/Train/BD_740', 'BD_755': f'{R}/Train/BD_755', 'BD_Test_Set_270': f'{R}/Test/BD_Test_Set_270'}
D = '/kaggle/temp/ds'
for s in ['train','val','test']:
    os.makedirs(f'{D}/images/{s}', exist_ok=True); os.makedirs(f'{D}/labels/{s}', exist_ok=True)
n = {'train':0,'val':0,'test':0}
for r in csv.DictReader(io.StringIO(SPLIT_CSV)):
    stem = f"{r['folder']}_{r['id']}"; p = f"{src[r['folder']]}/{r['id']}"
    os.symlink(p+'.jpg', f"{D}/images/{r['split']}/{stem}.jpg")
    shutil.copy(p+'.txt', f"{D}/labels/{r['split']}/{stem}.txt"); n[r['split']] += 1
open(f'{D}/data.yaml','w').write(f"path: {D}\ntrain: images/train\nval: images/val\ntest: images/test\nnames:\n  0: tree\n")

subprocess.run("pip install -q ultralytics", shell=True)
from ultralytics import YOLO, RTDETR
MODEL, SEED, TAG = "__MODEL__", __SEED__, "__NAME__"
t0=time.time()
m = (RTDETR if 'rtdetr' in MODEL else YOLO)(MODEL)
kw = dict(data=f'{D}/data.yaml', imgsz=__IMGSZ__, epochs=120, patience=__PATIENCE__, batch=__BATCH__, seed=SEED, deterministic=True,
          fliplr=0.5, device=0, workers=4, project='/kaggle/working/runs', name=TAG, exist_ok=True, plots=True)
if 'rtdetr' in MODEL: kw.update(epochs=80, patience=__RT_PATIENCE__, lr0=1e-4, optimizer='AdamW')
m.train(**kw)
best = (RTDETR if 'rtdetr' in MODEL else YOLO)(f'/kaggle/working/runs/{TAG}/weights/best.pt')
res = {}
for sp in ['val','test']:
    v = best.val(data=f'{D}/data.yaml', split=sp, imgsz=__IMGSZ__, batch=8, device=0, project='/kaggle/working/runs', name=f'eval_{sp}', exist_ok=True, save_json=False)
    res[sp] = dict(mAP50=float(v.box.map50), mAP75=float(v.box.map75), mAP50_95=float(v.box.map), P=float(v.box.mp), R=float(v.box.mr))
pr = best.predict(f'{D}/images/test', imgsz=__IMGSZ__, conf=0.001, device=0, verbose=False, stream=True)
with open(f'/kaggle/working/test_preds_{TAG}.csv','w') as f:
    f.write('image,x0,y0,x1,y1,score\n')
    for r in pr:
        for (a,b,c,d),s in zip(r.boxes.xyxyn.cpu().numpy(), r.boxes.conf.cpu().numpy()):
            f.write(f"{os.path.basename(r.path)},{a:.5f},{b:.5f},{c:.5f},{d:.5f},{s:.4f}\n")
shutil.copy(f"/kaggle/working/runs/{TAG}/weights/best.pt", f"/kaggle/working/{TAG}_best.pt")
res.update(counts=n, model=MODEL, seed=SEED, train_minutes=(time.time()-t0)/60)
json.dump(res, open(f'/kaggle/working/results_{TAG}.json','w'), indent=1); print(json.dumps(res, indent=1))
